custom_css:
@import url('https://fonts.googleapis.com/css2?family=Gowun+Batang:wght@400;700&family=Nanum+Myeongjo:wght@400;700;800&family=Noto+Serif+KR:wght@400;600&family=IBM+Plex+Mono:wght@400;500&display=swap');

/* 채팅 번호 앞의 '#' — 나눔명조 '#'(0.617em)을 숫자 폭(0.537em)에 맞춰 줄여 한 칸에 들어가게 합니다 */
@font-face {
    font-family: 'WG Hash';
    src: url(https://fonts.gstatic.com/l/font?kit=9Btx3DZF0dXLMZlywRbVRNhxy1LuYHEX&skey=c8f5ea5084209dd&v=v31) format('woff2');
    unicode-range: U+23;
    size-adjust: 87.03%;
    ascent-override: 91.92%;
    descent-override: 22.98%;
    line-gap-override: 0%;
    font-display: swap;
}

/* ==========================================================================
   원고지 · Wongoji — SillyTavern theme
   흰 종이, 먹, 그리고 청회색으로 인쇄된 원고지 칸.

   아래 :root 변수만 바꿔도 대부분의 인상을 조정할 수 있습니다.
   ========================================================================== */

:root {
    /* 종이와 먹 — 흑백 */
    --wg-desk: #ffffff;           /* 바탕 */
    --wg-paper: #ffffff;          /* 원고지 종이 */
    --wg-paper-user: #f3f5f7;     /* 유저 원고지 — 아주 옅은 청회색 */
    --wg-ink: #1c1e21;            /* 먹 */
    --wg-ink-body: #212327;       /* 본문 */
    --wg-ink-soft: #5b636c;       /* 옅은 먹 */
    --wg-ink-faint: #8d949b;      /* 연필 */

    /* 원고지 인쇄색 — 청회색 */
    --wg-print: #6d7f91;          /* 칸 테두리 */
    --wg-print-line: rgba(109, 127, 145, 0.55);
    --wg-print-faint: rgba(109, 127, 145, 0.20);
    --wg-wash: #e4e9ee;           /* 청회색 바탕 (인용) */

    /* 패널(설정·캐릭터 목록·월드 인포 등)은 옅은 회색 */
    --wg-ui-wash: #f1f1f1;
    --wg-ui-hover: #e8e8e8;
    --wg-ui-line: #d4d4d4;

    /* 밝은 바탕에서 쓰도록, 어두운 테마용 '흰색 반투명' 값을 먹색 반투명으로 바꿉니다.
       (SillyTavern 기본 스타일이 비활성 글자 등에 이 값을 씁니다) */
    --white20a: rgba(28, 30, 33, 0.16);
    --white30a: rgba(28, 30, 33, 0.38);
    --white50a: rgba(28, 30, 33, 0.55);
    --white70a: rgba(28, 30, 33, 0.7);

    /* 강조 */
    --wg-quote: #3f5a74;          /* “대사” — 청회색 */
    --wg-em: #6a6d72;             /* *지문·속마음* — 옅은 먹 */

    /* 폴라로이드 사진 필터. 흑백으로 보고 싶다면 grayscale(1) */
    --wg-photo-filter: none;

    /* ── 폴라로이드 아래 글귀 ─────────────────────────────
       따옴표 안의 글자만 바꾸면 됩니다. 예) '春風秋雨', '그날의 기록'
       花樣年華 (화양연화) — 인생에서 가장 아름다운 한때
       雪泥鴻爪 (설니홍조) — 눈 위에 남은 기러기 발자국, 덧없는 삶의 흔적  */
    --wg-caption-char: '花樣年華';
    --wg-caption-user: '雪泥鴻爪';


    /* 띠 위 여백에 인쇄된 이름 (토큰 수가 뒤에 붙습니다) */
    --wg-paper-label: '原稿用紙';

    /* 서체 */
    --wg-serif: 'Gowun Batang', 'Nanum Myeongjo', 'Noto Serif KR', serif;
    --wg-title: 'Nanum Myeongjo', 'Noto Serif KR', 'Gowun Batang', serif;
    --wg-hanja: 'Noto Serif KR', 'Nanum Myeongjo', serif;   /* 한자가 있는 명조 */
    --wg-mono: 'IBM Plex Mono', 'D2Coding', ui-monospace, monospace;

    /* 본문: 글자 크기와 행간 */
    /* 테마의 기본 글자 크기(Font Scale)는 0.8 — 본문은 그만큼 보정해 이전 크기를 유지합니다 */
    --wg-text: calc(var(--mainFontSize) * 1.21);
    --wg-lh: calc(var(--wg-text) * 1.85);
    --wg-measure: clamp(14px, 6%, 44px);  /* 본문 좌우 여백 */

    /* 꾸밈 글자 */
    --wg-spine-char: 'MANUSCRIPT \00B7  原稿';
    --wg-spine-user: 'REPLY \00B7  答書';
    --wg-endmark: '\25C7';

    /* 머리 원고지 띠 */
    --wg-cell: 32px;              /* 칸 */
    --wg-gap: 8px;                /* 줄 사이 틈 */
    --wg-pad: 74px;               /* 구분선과 띠 사이 */
    --wg-after: 108px;            /* 본문 끝과 다음 구분선 사이 */
    --wg-side: 18px;
    --wg-photo: 128px;
    --wg-frame: 7px;
    --wg-chin: 28px;
    --wg-tilt: -4deg;

    /* 상단 메뉴 · 입력창 아이콘 */
    --topBarIconSize: calc(var(--mainFontSize) * 1.05);
    --topBarBlockPadding: 22px;
    --bottomFormIconSize: calc(var(--mainFontSize) * 1.4);

    --mainFontFamily: var(--wg-serif);
    --monoFontFamily: var(--wg-mono);
}

@media (max-width: 600px) {
    :root {
        --wg-cell: 25px;
        --wg-gap: 6px;
        --wg-pad: 62px;
        --wg-after: 92px;
        --wg-side: 10px;
        --wg-photo: 100px;
        --wg-frame: 5px;
        --wg-chin: 22px;
        --topBarIconSize: calc(var(--mainFontSize) * 1.15);
        --bottomFormIconSize: calc(var(--mainFontSize) * 1.5);
    }
}

/* ----------------------------------------------------------------------------
   책상과 종이
   ---------------------------------------------------------------------------- */

body {
    background-color: var(--wg-desk);
    font-family: var(--wg-serif);
    text-shadow: none;
}

#bg1 {
    background: var(--wg-desk) !important;
    opacity: 1 !important;
}

#chat {
    background-color: transparent;
    text-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    padding: 0 6px;
    scrollbar-color: rgba(28, 30, 33, 0.25) transparent;
}

::selection {
    background: rgba(109, 127, 145, 0.28);
    color: var(--wg-ink);
}

/* ----------------------------------------------------------------------------
   상단 메뉴 — 작은 아이콘, 책 머리말 같은 이중 괘선
   ---------------------------------------------------------------------------- */

#top-bar {
    /* 기본값은 입력창 높이를 쓰므로, 메뉴 칸 높이에 맞춰 선이 아이콘 아래로 오게 합니다 */
    height: var(--topBarBlockSize);
    background-color: var(--wg-paper);
    box-shadow: none;
    border-bottom: 1px solid var(--wg-print-faint);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

#top-settings-holder {
    justify-content: center;
    align-items: center;
    gap: clamp(6px, 3.2vw, 34px);
}

#top-settings-holder > .drawer {
    flex: 0 0 auto;
    width: auto;
    height: 100%;
    align-items: center;
    justify-content: center;
}

#top-settings-holder .drawer-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
}

#top-settings-holder .drawer-icon {
    color: var(--wg-ink);
    font-size: var(--topBarIconSize);
    line-height: 1;
    padding: 4px;
}

#top-settings-holder .drawer-icon.closedIcon {
    opacity: 0.42;
}

#top-settings-holder .drawer-icon.closedIcon:hover,
#top-settings-holder .drawer-icon.openIcon {
    opacity: 1;
}

/* ----------------------------------------------------------------------------
   메시지 한 장
   .mesAvatarWrapper 를 풀어(display: contents) 아바타·번호·타이머를
   .mes 기준으로 배치합니다.
   ---------------------------------------------------------------------------- */

#chat .mes {
    --wg-pitch: calc(var(--wg-cell) + var(--wg-gap));
    --wg-pol-w: calc(var(--wg-photo) + var(--wg-frame) * 2);
    --wg-pol-h: calc(var(--wg-photo) + var(--wg-frame) + var(--wg-chin));
    --wg-band-near: calc(var(--wg-side) + var(--wg-pol-w) * 0.42);
    --wg-band-far: var(--wg-side);
    /* 칸 글꼴: 나눔명조, 글자 크기 = 칸의 75%. 한글 0.95em + 자간 = 한 칸 */
    --wg-cell-font: calc(var(--wg-cell) * 0.75);
    --wg-track: calc(var(--wg-cell) * 0.2875);
    --wg-cell-family: 'Nanum Myeongjo', 'Noto Serif KR', serif;
    --wg-band-bg: var(--wg-paper);
    /* 캐릭터 원고지는 먹색 선 */
    --wg-band-frame: var(--wg-ink);
    --wg-band-line: rgba(28, 30, 33, 0.62);

    /* 1행: 폴라로이드 + 원고지 띠 / 2행: 버튼 / 그 아래: 본문 */
    display: grid;
    grid-template-columns:
        calc(var(--wg-pol-w) * 0.42)
        calc(var(--wg-pol-w) * 0.58)
        minmax(0, 1fr);
    align-items: start;
    position: relative;
    padding: var(--wg-pad) var(--wg-side) var(--wg-after);
    margin: 0;
    /* 구분선 — 원고지 낱장의 머리처럼, 칸마다 눈금을 새긴 자 */
    border-top: 1px solid var(--wg-ink);
    background-color: transparent;
    background-image:
        linear-gradient(to right, var(--wg-print) 1px, transparent 1px),
        linear-gradient(to right, var(--wg-print-line) 1px, transparent 1px),
        linear-gradient(var(--wg-print-faint), var(--wg-print-faint));
    background-size: calc(var(--wg-cell) * 5) 9px, var(--wg-cell) 5px, 100% 1px;
    background-repeat: repeat-x, repeat-x, no-repeat;
    background-position:
        right var(--wg-side) top 0,
        right var(--wg-side) top 0,
        0 4px;
    color: var(--wg-ink-body);
    overflow: visible;
}

#chat .mes:first-child {
    margin-top: 14px;
}

#chat .mes.last_mes {
    margin-bottom: 0;
}

/* 폴라로이드 아래 글씨 — 아바타와 같은 상자를 같은 각도로 */
#chat .mes .avatar::after {
    content: var(--wg-caption-char);
    position: absolute;
    left: var(--wg-frame);
    right: var(--wg-frame);
    bottom: calc(var(--wg-chin) * 0.2);
    text-align: right;
    font-family: var(--wg-hanja);
    font-size: calc(var(--wg-chin) * 0.32);
    font-weight: 400;
    letter-spacing: 0.3em;
    line-height: 1.2;
    color: var(--wg-ink-soft);
    white-space: nowrap;
    overflow: hidden;
    pointer-events: none;
}

#chat .mes .mesAvatarWrapper,
#chat .mes .mes_block,
#chat .mes .ch_name,
#chat .mes .ch_name > .flex-container {
    display: contents;
}

#chat .mes .for_checkbox {
    position: absolute;
    width: 0;
    height: 0;
}

#chat .mes .mes_reasoning_details { grid-row: 3; grid-column: 1 / -1; }
#chat .mes .mes_text              { grid-row: 4; grid-column: 1 / -1; }
#chat .mes .mes_media_wrapper     { grid-row: 5; grid-column: 1 / -1; }
#chat .mes .mes_file_wrapper      { grid-row: 6; grid-column: 1 / -1; }
#chat .mes .mes_bias              { grid-row: 7; grid-column: 1 / -1; }

/* 폴라로이드 */
#chat .mes .avatar {
    /* 띠 높이와 상관없이 띠의 세로 가운데에. 위아래 음수 여백으로 행 높이에는 끼어들지 않습니다 */
    grid-row: 1;
    grid-column: 1 / 3;
    align-self: center;
    justify-self: start;
    position: relative;
    margin: calc(var(--wg-pol-h) / -2) 0;
    width: var(--wg-pol-w);
    height: var(--wg-pol-h);
    box-sizing: border-box;
    padding: var(--wg-frame) var(--wg-frame) var(--wg-chin);
    flex: none;
    background: #ffffff;
    border-radius: 1px;
    transform: rotate(var(--wg-tilt));
    border: 1px solid var(--wg-band-frame);
    box-shadow: none;
    z-index: 2;
    transition: transform var(--animation-duration-2x) ease;
}

#chat .mes .avatar:hover {
    transform: rotate(0deg) scale(1.03);
}

#chat .mes .avatar img {
    width: var(--wg-photo);
    height: var(--wg-photo);
    box-sizing: border-box;
    border-radius: 0;
    border: 1px solid var(--wg-band-frame);
    box-shadow: none;
    object-fit: cover;
    filter: var(--wg-photo-filter);
    transition: filter var(--animation-duration-2x) ease;
}

/* 띠 위 여백의 작은 인쇄 글씨: 생성 시간 */
#chat .mes .mes_timer {
    position: absolute;
    top: calc(var(--wg-pad) - 20px);
    height: 14px;
    line-height: 14px;
    margin: 0;
    padding: 0;
    font-family: var(--wg-mono);
    font-size: 10.5px;
    font-weight: 400;
    letter-spacing: 0.04em;
    color: var(--wg-ink-faint);
    opacity: 1;
    white-space: nowrap;
    z-index: 1;
}

/* 날짜 — 이름 위 줄 */
/* 날짜 — 원고지 아래 여백에 인쇄된 작은 글씨 */
#chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    position: absolute;
    top: calc(100% + 9px);
    right: -1px;
    width: auto !important;
    max-width: none !important;
    font-family: var(--wg-title) !important;
    font-size: 10.5px !important;
    font-weight: 700;
    line-height: 16px !important;
    letter-spacing: 0.06em !important;
    word-spacing: 0.1em;
    white-space: nowrap !important;
    color: var(--wg-ink-soft);
}

#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container > .timestamp {
    right: auto;
    left: -1px;
}

/* 첫째 줄 — 채팅 번호 자리 (번호는 .mes::before 가 위에 겹쳐 적습니다) */
#chat .mes .ch_name > .flex-container > .flex-container::before {
    content: '\00A0';
    order: -1;
    display: block;
    align-self: stretch;
    position: relative;
    top: 0.055em;
    font-weight: 400;
    word-spacing: calc(var(--wg-cell) - var(--wg-cell-font) * 0.27 - var(--wg-track));
    color: var(--wg-ink-soft);
    white-space: normal;
    word-break: keep-all;
}

/* 채팅 번호 — 첫째 줄에 숫자 한 칸에 한 자씩.
   나눔명조 숫자는 폭이 0.537em 으로 모두 같아 자간으로 칸에 맞춥니다 */
#chat .mes::before {
    --wg-digit-track: calc(var(--wg-cell) - var(--wg-cell-font) * 0.537);
    content: '#' attr(mesid);
    grid-row: 1;
    grid-column: 2 / 4;
    align-self: start;
    justify-self: end;
    position: relative;
    top: 0.055em;
    z-index: 1;
    margin-top: calc(1px + var(--wg-gap) / 2);
    margin-right: calc(var(--wg-cell) - var(--wg-digit-track) / 2);
    height: var(--wg-pitch);
    font-family: 'WG Hash', var(--wg-cell-family);
    font-size: var(--wg-cell-font);
    font-weight: 400;
    line-height: var(--wg-pitch);
    letter-spacing: var(--wg-digit-track);
    color: var(--wg-ink-soft);
    white-space: nowrap;
    pointer-events: none;
}

#chat .mes[is_user="true"]::before {
    grid-column: 1 / 3;
    justify-self: start;
    margin-right: 0;
    margin-left: calc(var(--wg-cell) + var(--wg-digit-track) / 2);
}

body.no-mesIDDisplay #chat .mes::before {
    content: none;
}

#chat .mes .mesIDDisplay {
    display: none !important;
}

#chat .mes .mes_timer {
    right: var(--wg-band-far);
}

/* 원고지 머리 여백에 인쇄된 표기 */
#chat .mes .tokenCounterDisplay,
#chat .mes .ch_name::after {
    position: absolute;
    top: calc(var(--wg-pad) - 20px);
    left: calc(var(--wg-side) + var(--wg-pol-w) + 8px);
    height: 14px;
    margin: 0;
    padding: 0;
    line-height: 14px;
    font-family: var(--wg-title);
    font-weight: 700;
    font-size: 10px;
    letter-spacing: 0.12em;
    /* 캐릭터는 먹색, 유저는 청회색 — 원고지 선과 같은 색 */
    color: var(--wg-band-frame);
    opacity: 1;
    white-space: nowrap;
    z-index: 1;
}

/* 토큰 수 표시를 켜면: 原稿用紙 · 412t */
#chat .mes .tokenCounterDisplay::before {
    content: var(--wg-paper-label) '\00A0\00B7\00A0';
    font-family: var(--wg-title);
    font-weight: 700;
    letter-spacing: 0.22em;
}

#chat .mes .tokenCounterDisplay:empty::before {
    content: var(--wg-paper-label);
}

/* 토큰 수 표시를 끄면 이름만 */
#chat .mes .ch_name::after {
    content: none;
    font-family: var(--wg-title);
    font-weight: 700;
    letter-spacing: 0.22em;
}

body.no-tokenCount #chat .mes .ch_name::after {
    content: var(--wg-paper-label);
}

/* 원고지 띠 — 날짜와 이름을 담은 상자 자체에 칸을 그립니다.
   글이 길면 줄이 늘고, 띠도 함께 늘어납니다.
   한글은 한 칸에 한 자, 띄어쓰기도 한 칸 */
#chat .mes .mes_block,
#chat .mes .ch_name,
#chat .mes .ch_name > .flex-container {
    position: static;
}

#chat .mes .ch_name > .flex-container > .flex-container {
    --wg-k: 1;                    /* 끝에서 비워 둘 칸 */
    grid-row: 1;
    grid-column: 2 / 4;
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 0;
    width: auto;
    margin: 0 0 16px;
    /* 폴라로이드 쪽은 가리지 않도록 비우고, 끝은 칸 경계에 맞춥니다 */
    padding:
        calc(var(--wg-gap) / 2)
        calc(var(--wg-cell) * var(--wg-k) - var(--wg-track) / 2 - 1px)
        calc(var(--wg-gap) / 2)
        calc(var(--wg-pol-w) - var(--wg-pol-w) * 0.42 + 8px);
    border: 1px solid var(--wg-band-frame);
    outline: 1px solid var(--wg-band-frame);
    outline-offset: 2px;
    background-color: var(--wg-band-bg);
    background-image:
        linear-gradient(to bottom,
            transparent var(--wg-gap),
            var(--wg-band-line) var(--wg-gap), var(--wg-band-line) calc(var(--wg-gap) + 1px),
            transparent calc(var(--wg-gap) + 1px), transparent calc(var(--wg-pitch) - 1px),
            var(--wg-band-line) calc(var(--wg-pitch) - 1px)),
        linear-gradient(to bottom, var(--wg-band-bg) var(--wg-gap), transparent var(--wg-gap)),
        linear-gradient(to right, var(--wg-band-line) 1px, transparent 1px);
    background-size: 100% var(--wg-pitch), 100% var(--wg-pitch), var(--wg-cell) 100%;
    background-position: 0 0, 0 0, right -1px top 0;
    background-repeat: repeat;
    font-family: var(--wg-cell-family);
    font-size: var(--wg-cell-font);
    line-height: var(--wg-pitch);
    letter-spacing: var(--wg-track);
    text-align: right;
}

#chat .mes .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    display: block;
    align-self: stretch;
    width: 100%;
    max-width: 100%;
    margin: 0;
    padding: 0;
    font-family: inherit;
    font-size: inherit;
    line-height: inherit;
    letter-spacing: inherit;
    text-align: inherit;
    white-space: normal;
    word-break: keep-all;
    overflow-wrap: anywhere;
    opacity: 1;
}

#chat .mes .name_text {
    position: relative;
    /* 명조 한글의 먹 중심이 줄 가운데보다 0.055em 위에 있어 그만큼 내립니다 */
    top: 0.055em;
    font-weight: 700;
    /* 띄어쓰기도 한 칸 */
    word-spacing: calc(var(--wg-cell) - var(--wg-cell-font) * 0.27 - var(--wg-track));
    color: var(--wg-ink);
}

/* 영문 이름 — 영문 글자로 시작하는 이름은 칸 자간을 풀고 촘촘하게 적습니다.
   (CSS로는 글자마다 자간을 다르게 줄 수 없어, 이름의 첫 글자로 구분합니다) */
#chat .mes[ch_name^="a" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="b" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="c" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="d" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="e" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="f" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="g" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="h" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="i" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="j" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="k" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="l" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="m" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="n" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="o" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="p" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="q" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="r" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="s" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="t" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="u" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="v" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="w" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="x" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="y" i] .ch_name > .flex-container > .flex-container > .name_text,
#chat .mes[ch_name^="z" i] .ch_name > .flex-container > .flex-container > .name_text {
    letter-spacing: 0.03em;
    word-spacing: 0.2em;
}

#chat .mes .mes_ghost {
    position: absolute;
    top: 2px;
    left: calc(var(--wg-pol-w) * 0.58 + 6px);
    font-size: 11px;
    line-height: 1;
    letter-spacing: 0;
    color: var(--wg-ink-faint);
}

#chat .mes .mes_block {
    padding: 0;
    width: 100%;
    overflow: visible;
}

/* 메시지 버튼 — 띠와 본문 사이, 양옆으로 가는 괘선을 그은 구분 줄 */
#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons {
    justify-content: center;
    align-items: center;
    align-self: stretch;
    float: none;
    gap: 2px;
    grid-row: 2;
    grid-column: 1 / -1;
    /* 날짜의 28px 영역과 폴라로이드 돌출부를 함께 계산합니다. */
    margin: max(8px, calc((var(--wg-pol-h) - var(--wg-pitch) * 2 - var(--wg-gap) - 28px) / 2 + 6px)) var(--wg-measure) 12px;
    min-height: 32px;
    overflow: visible;
}

#chat .mes .mes_buttons::before,
#chat .mes .mes_buttons::after,
#chat .mes .mes_edit_buttons::before,
#chat .mes .mes_edit_buttons::after {
    content: '';
    flex: 1 1 0;
    min-width: 12px;
    height: 5px;
    margin: 0 10px;
    border-top: 1px solid var(--wg-print-line);
    border-bottom: 1px solid var(--wg-print-faint);
}

#chat .mes .mes_button,
#chat .mes .extraMesButtons > div {
    color: var(--wg-ink);
    filter: none;
    opacity: 0.35;
    padding: 4px 7px;
    font-size: 13px;
}

#chat .mes .mes_button:hover,
#chat .mes .extraMesButtons > div:hover {
    opacity: 1;
}

#chat .mes .mes_edit_buttons .menu_button {
    background: var(--wg-paper);
    border: 1px solid rgba(28, 30, 33, 0.22);
    border-radius: 999px;
    color: var(--wg-ink);
    width: 30px;
    height: 30px;
    font-size: 12px;
    opacity: 0.8;
    filter: none;
}

#chat .mes .mes_edit_buttons .menu_button:hover {
    opacity: 1;
    border-color: var(--wg-ink);
}

/* ----------------------------------------------------------------------------
   본문 — 원고지 한 장에 쓴 글
   줄마다 칸 줄(행)과 그 사이의 틈이 번갈아 지나갑니다.
   ---------------------------------------------------------------------------- */

#chat .mes .mes_text {
    position: relative;
    margin: 0;
    padding: 2px var(--wg-measure) 0;
    background: none;
    border: 0;
    box-shadow: none;
    font-family: var(--wg-serif);
    font-size: var(--wg-text);
    font-weight: 400;
    line-height: var(--wg-lh);
    color: var(--wg-ink-body);
    letter-spacing: 0.01em;
    word-break: keep-all;
    overflow-wrap: anywhere;
    overflow-x: auto;
    text-shadow: none;
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
}

#chat .mes .mes_text:empty {
    display: none;
}

#chat .mes .mes_text p {
    margin: 0 0 0.95em;
}

#chat .mes .mes_text > :last-child {
    margin-bottom: 0;
}

/* 글 끝 표시 — 잡지 기사의 마침 기호처럼 */
#chat .mes .mes_text > p:last-child::after {
    content: var(--wg-endmark);
    display: inline-block;
    margin-left: 0.6em;
    font-size: 0.62em;
    line-height: 1;
    vertical-align: 0.2em;
    color: var(--wg-print);
}

#chat .mes .mes_text br {
    margin: 0;
}

#chat .mes .mes_text q {
    color: var(--wg-quote);
}

#chat .mes .mes_text em,
#chat .mes .mes_text i {
    color: var(--wg-em);
    font-style: normal;
}

#chat .mes .mes_text q em,
#chat .mes .mes_text q i {
    color: inherit;
}

#chat .mes .mes_text strong {
    font-weight: 700;
    color: var(--wg-ink);
}

#chat .mes .mes_text u {
    color: inherit;
    text-decoration-color: var(--wg-print);
    text-decoration-thickness: 1px;
    text-underline-offset: 5px;
}

/* 장면 전환 */
#chat .mes .mes_text hr {
    border: 0;
    height: var(--wg-lh);
    margin: 0.4em 0 0.9em;
    opacity: 1;
    background: none;
}

#chat .mes .mes_text hr::after {
    content: '＊';
    display: block;
    text-align: center;
    line-height: var(--wg-lh);
    font-size: 0.9em;
    color: var(--wg-ink-soft);
}

/* 인용 — 책 뒤표지의 제사(題辭)처럼 */
#chat .mes .mes_text blockquote {
    margin: 0.4em clamp(0px, 4%, 24px) 1.2em;
    padding: 0.9em 1.4em;
    background: var(--wg-wash);
    border: 0;
    border-radius: 2px;
    color: var(--wg-ink);
    text-align: center;
    font-family: var(--wg-title);
    line-height: 1.9;
}

#chat .mes .mes_text blockquote::before {
    content: '\201C';
    display: block;
    height: 0.55em;
    font-family: var(--wg-title);
    font-size: 2.2em;
    line-height: 1;
    color: var(--wg-print);
}

#chat .mes .mes_text blockquote p {
    margin: 0;
}

/* 장 제목 */
#chat .mes .mes_text h1,
#chat .mes .mes_text h2,
#chat .mes .mes_text h3,
#chat .mes .mes_text h4 {
    font-family: var(--wg-title);
    font-weight: 700;
    line-height: var(--wg-lh);
    margin: 0.4em 0 0.8em;
    font-size: 1.05em;
    text-align: center;
    letter-spacing: 0.2em;
    color: var(--wg-ink);
}

#chat .mes .mes_text h1 {
    font-size: 1.2em;
}

#chat .mes .mes_text ul,
#chat .mes .mes_text ol {
    margin: 0;
    padding-left: 2em;
}

#chat .mes .mes_text code {
    font-family: var(--wg-mono);
    font-size: 0.86em;
    background: var(--wg-wash);
    border: 0;
    border-radius: 3px;
    padding: 0.1em 0.35em;
    color: var(--wg-ink);
}

#chat .mes .mes_text pre {
    margin: calc(var(--wg-lh) * 0.25) 0;
    line-height: 1.6;
}

#chat .mes .mes_text pre code {
    display: block;
    padding: 12px 14px;
    background: #f1f3f5;
    border: 1px solid var(--wg-print-faint);
    border-radius: 6px;
    text-shadow: none;
}

#chat .mes .mes_text img {
    border-radius: 2px;
    max-width: 100%;
}

#chat .mes .mes_text table {
    border-collapse: collapse;
    background: var(--wg-paper);
    line-height: 1.7;
}

#chat .mes .mes_text th,
#chat .mes .mes_text td {
    border: 1px solid var(--wg-print-line);
    padding: 3px 10px;
}

#chat .mes .mes_text a {
    color: var(--wg-ink);
    text-decoration-color: var(--wg-print);
    text-underline-offset: 4px;
}

/* 편집 중 — 카드는 비우고 입력창이 원고가 됩니다 */
#chat .mes .mes_text:has(.edit_textarea) {
    padding: 0;
}

#chat .mes .edit_textarea {
    margin: 0;
    padding: 12px var(--wg-measure);
    background: var(--wg-paper);
    border: 1px solid var(--wg-ink);
    border-radius: 12px;
    box-shadow: 0 0 0 3px var(--wg-paper), 0 0 0 4px var(--wg-print-line);
    font-family: var(--wg-serif);
    font-size: var(--wg-text);
    line-height: 1.9;
    color: var(--wg-ink);
}

/* 생각(추론) — 원고 여백의 퇴고 메모. 접으면 한 줄, 펼치면 왼쪽 괘선 아래 작은 글씨 */
#chat .mes .mes_reasoning_details {
    margin: 0 var(--wg-measure) 14px;
    padding: 0;
    background: none;
    border: 0;
    border-radius: 0;
}

#chat .mes .mes_reasoning_summary {
    margin: 0;
    align-items: center;
    font-family: var(--wg-title);
    font-size: 12px;
    color: var(--wg-ink-soft);
}

#chat .mes .mes_reasoning_header {
    margin: 0;
    padding: 2px 18px 2px 0;
    background: none;
    border: 0;
    border-radius: 0;
    font-family: var(--wg-title);
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--wg-ink-soft);
    align-items: center;
    gap: 8px;
}

#chat .mes .mes_reasoning_header::before {
    content: '註';
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    flex: none;
    border: 1px solid var(--wg-print);
    font-family: var(--wg-hanja);
    font-size: 11px;
    font-weight: 400;
    letter-spacing: 0;
    color: var(--wg-print);
}

#chat .mes .mes_reasoning_header_title {
    margin: 0;
    border-bottom: 1px dotted var(--wg-print-line);
}

#chat .mes .mes_reasoning_arrow {
    right: 0;
    color: var(--wg-print);
}

#chat .mes .mes_reasoning_actions .mes_button {
    font-size: 12px;
}

#chat .mes .mes_reasoning {
    margin: 8px 0 2px 8px;
    padding: 2px 0 2px 16px;
    border-left: 1px solid var(--wg-print-line);
    font-family: var(--wg-serif);
    font-size: calc(var(--wg-text) * 0.86);
    line-height: 1.75;
    color: var(--wg-ink-soft);
    max-height: 40vh;
    overflow-y: auto;
}

/* 스와이프 */
#chat .mes .swipe_left,
#chat .mes .swipe_right {
    color: var(--wg-ink);
    font-size: 14px;
    opacity: 0.4;
    filter: none;
}

#chat .mes .swipe_left:hover,
#chat .mes .swipe_right:hover {
    opacity: 1;
}

#chat .mes .swipe_left {
    left: var(--wg-side);
    bottom: 10px;
}

#chat .mes .swipeRightBlock {
    right: var(--wg-side);
    bottom: 10px;
    flex-direction: row-reverse;
    align-items: center;
    gap: 4px;
}

#chat .mes .swipes-counter {
    font-family: var(--wg-mono);
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--wg-ink-soft);
    margin: 0;
    min-width: 0;
    height: auto;
}

/* 책등 — 본문 옆에 세로로 인쇄된 표기 */
#chat .mes .mes_text::before {
    content: var(--wg-spine-char);
    position: absolute;
    top: 6px;
    bottom: 4px;
    left: 0;
    width: 14px;
    box-sizing: border-box;
    border-right: 1px solid var(--wg-print-faint);
    writing-mode: vertical-rl;
    font-family: var(--wg-mono);
    font-size: 8.5px;
    letter-spacing: 0.32em;
    line-height: 14px;
    color: var(--wg-print);
    white-space: nowrap;
    overflow: hidden;
    pointer-events: none;
}

#chat .mes[is_user="true"] .mes_text::before {
    content: var(--wg-spine-user);
    left: auto;
    right: 0;
    border-right: 0;
    border-left: 1px solid var(--wg-print-faint);
}

#chat .mes .mes_text:has(.edit_textarea)::before {
    display: none;
}

@media (max-width: 600px) {
    #chat .mes .mes_text::before {
        width: 12px;
        line-height: 12px;
        font-size: 7.5px;
        letter-spacing: 0.26em;
    }

    #chat .mes .mes_text {
        padding-left: 26px;
        padding-right: 8px;
    }

    #chat .mes[is_user="true"] .mes_text {
        padding-left: 8px;
        padding-right: 26px;
    }
}

/* ----------------------------------------------------------------------------
   유저 메시지 — 좌우를 뒤집어 맞은편 페이지처럼
   ---------------------------------------------------------------------------- */

#chat .mes[is_user="true"] {
    --wg-tilt: 4deg;
    --wg-band-bg: var(--wg-paper-user);
    --wg-band-frame: var(--wg-print);
    --wg-band-line: var(--wg-print-line);
    background-position:
        left var(--wg-side) top 0,
        left var(--wg-side) top 0,
        0 4px;
}

#chat .mes[is_user="true"] {
    grid-template-columns:
        minmax(0, 1fr)
        calc(var(--wg-pol-w) * 0.58)
        calc(var(--wg-pol-w) * 0.42);
}

#chat .mes[is_user="true"] .avatar {
    grid-column: 2 / 4;
    justify-self: end;
}

#chat .mes[is_user="true"] .avatar::after {
    content: var(--wg-caption-user);
    text-align: left;
}

#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container {
    align-items: flex-start;
    grid-column: 1 / 3;
    margin: 0 0 16px;
    padding:
        calc(var(--wg-gap) / 2)
        calc(var(--wg-pol-w) - var(--wg-pol-w) * 0.42 + 8px)
        calc(var(--wg-gap) / 2)
        calc(var(--wg-cell) * var(--wg-k) + var(--wg-track) / 2 - 1px);
    /* 첫 세로 칸선을 테두리 아래로 숨겨 왼쪽 끝이 한 줄로 겹치게 */
    background-position: 0 0, 0 0, left -1px top 0;
    text-align: left;
}

#chat .mes[is_user="true"] .mes_timer {
    right: auto;
    left: var(--wg-band-far);
}

#chat .mes[is_user="true"] .tokenCounterDisplay,
#chat .mes[is_user="true"] .ch_name::after {
    left: auto;
    right: calc(var(--wg-side) + var(--wg-pol-w) + 8px);
}

#chat .mes[is_user="true"] .mes_ghost {
    left: auto;
    right: calc(var(--wg-pol-w) * 0.58 + 6px);
}

/* 시스템 메시지 */
#chat .mes[is_system="true"] .mes_text {
    color: var(--wg-ink-soft);
}

/* 아바타 숨김 설정 — 띠만 남깁니다 */
body.hideChatAvatars #chat .mes {
    --wg-band-near: var(--wg-side);
    --wg-pol-w: 0px;
}

/* 선택(삭제 모드) */
#chat .mes.selected {
    background-color: rgba(28, 30, 33, 0.06);
}

#chat .mes .del_checkbox {
    position: absolute;
    top: 8px;
    left: 8px;
    z-index: 5;
}

/* 컨텍스트 경계 */
#chat .mes.lastInContext {
    border-top: 1px dashed var(--wg-print) !important;
}

/* ----------------------------------------------------------------------------
   하단 입력창 — 원고지 한 줄
   ---------------------------------------------------------------------------- */

#form_sheld {
    margin-top: 0;
}

#send_form {
    background-color: var(--wg-paper);
    border: 0;
    border-top: 1px solid var(--wg-print-faint);
    border-radius: 0;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    padding: 4px 4px 6px;
}

#send_form:has(#send_textarea:focus-visible) {
    outline: none;
    border-color: var(--wg-print-line);
}

@media screen and (max-width: 1000px) {
    #leftSendForm,
    #rightSendForm {
        width: auto;
        flex-wrap: nowrap;
        height: auto;
    }
}

/* 입력창 아이콘 — 입력칸과 세로 가운데 맞춤 */
#nonQRFormItems {
    align-items: center;
}

#leftSendForm,
#rightSendForm {
    align-self: center;
    align-items: center;
}

#leftSendForm > div,
#rightSendForm > div {
    display: flex;
    align-items: center;
    justify-content: center;
}

#send_textarea {
    font-family: var(--wg-serif);
    font-size: var(--wg-text);
    line-height: 1.75;
    color: var(--wg-ink);
    text-shadow: none;
    padding: 8px 10px;
    background-image: linear-gradient(transparent calc(100% - 1px), var(--wg-print-line) calc(100% - 1px));
    --progColor: var(--wg-print);
}

#send_textarea::placeholder {
    color: var(--wg-ink-faint);
    font-style: normal;
}

#leftSendForm > div,
#rightSendForm > div:not(.mes_stop),
#send_form .mes_stop {
    color: var(--wg-ink);
    opacity: 0.5;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    opacity: 1;
    filter: none;
}

/* ----------------------------------------------------------------------------
   패널 · 팝업 — 같은 종이 위에서. 옅은 회색 선과 바탕만, 그림자 없음
   ---------------------------------------------------------------------------- */

/* 그림자 — 글자와 이미지 모두 없앱니다 */
body,
body * {
    text-shadow: none !important;
}

img,
.avatar,
.avatar img,
.bg_example,
.character_select .avatar img,
.group_select .avatar img,
.menu_button,
.menu_button_icon,
.drawer-content,
.popup,
#character_popup,
#WorldInfo,
.options-content,
.list-group,
#extensionsMenu,
#toast-container > div {
    box-shadow: none !important;
}

.mes_button,
.extraMesButtons > div,
.inline-drawer-icon,
.custom-drawer-icon,
.drawer-icon {
    filter: none !important;
}

.drawer-content,
#left-nav-panel,
#right-nav-panel,
.popup,
#character_popup,
#WorldInfo,
.options-content,
.list-group,
#extensionsMenu {
    background-color: var(--wg-paper);
    color: var(--wg-ink);
    border-color: var(--wg-ui-line);
}

.menu_button,
.menu_button_icon,
.right_menu_button {
    color: var(--wg-ink);
}

.menu_button {
    background-color: var(--wg-ui-wash);
    border: 1px solid var(--wg-ui-line);
    filter: none;
}

.menu_button:hover {
    background-color: var(--wg-ui-hover);
}

.text_pole,
textarea,
select,
input[type="text"],
input[type="number"],
input[type="search"] {
    background-color: #ffffff;
    color: var(--wg-ink);
    border: 1px solid var(--wg-ui-line);
}

/* 기본 스타일이 글자·아이콘에 거는 검은 그림자 필터도 걷어 냅니다 */
.dragClose,
.ch_fav_icon,
.mes_edit_buttons,
.mes_img_swipe_counter,
.draggable,
.zoomed_avatar,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt span span span,
#completion_prompt_manager .completion_prompt_manager_header_advanced span {
    filter: none !important;
}

/* 선택 상자(월드 선택 등) — 어두운 반투명 바탕 대신 흰 종이 */
.select2-container .select2-selection--multiple,
.select2-container .select2-selection--single,
.select2-search__field {
    background-color: #ffffff !important;
    border-color: var(--wg-ui-line) !important;
    color: var(--wg-ink);
}

.select2-container .select2-selection--multiple .select2-selection__choice,
.select2-container .select2-selection--single .select2-selection__choice {
    background-color: var(--wg-ui-wash) !important;
    border-color: var(--wg-ui-line) !important;
    color: var(--wg-ink);
}

.select2-dropdown,
.select2-results__option {
    background-color: #ffffff;
    color: var(--wg-ink);
}

.select2-results__option--highlighted {
    background-color: var(--wg-ui-hover) !important;
    color: var(--wg-ink) !important;
}

/* 접기 머리 — 옅은 회색 띠 */
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background-image: none;
    background-color: var(--wg-ui-wash);
    border: 0;
    border-bottom: 1px solid var(--wg-ui-line);
    border-radius: 3px 3px 0 0;
    color: var(--wg-ink);
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover,
.standoutHeader.inline-drawer-header:hover {
    filter: none;
    background-color: var(--wg-ui-hover);
}

.standoutHeader ~ .inline-drawer-content {
    background-color: #ffffff;
    border-color: var(--wg-ui-line);
}

/* 접기 화살표 — 검은 동그라미 대신 가는 회색 */
.inline-drawer-icon {
    color: var(--wg-ink-faint);
    font-size: calc(var(--mainFontSize) * 1.25);
}

#extensionsMenu > .extension_container > div,
#extensionsMenu > div:not(.extension_container),
.options-content a,
.list-group-item {
    opacity: 0.85;
}

.list-group-item:hover,
.options-content a:hover {
    background-color: var(--wg-ui-hover);
}

h1, h2, h3, h4, h5,
.standoutHeader {
    font-family: var(--wg-title);
    letter-spacing: 0.01em;
}

/* 캐릭터 · 페르소나 목록 — 이미지에 가는 선 */
.character_select .avatar img,
.group_select .avatar img,
#user_avatar_block .avatar img,
.avatar-container .avatar img,
#avatar_div_div img,
.bogus_folder_select .avatar {
    border: 1px solid var(--wg-ui-line);
}

.character_select.selected,
.group_select.selected,
.avatar-container.selected {
    background-color: var(--wg-ui-wash);
}

/* 월드 인포 항목 */
.world_entry,
.world_entry_form {
    border-color: var(--wg-ui-line) !important;
    background-color: #ffffff;
}

/* 프롬프트 관리자 — 꺼진 항목도 읽히게 */
#completion_prompt_manager #completion_prompt_manager_list li {
    border-color: var(--wg-ui-line);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
    color: var(--wg-ink-faint);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
    border: 1px dashed var(--wg-ui-line);
}

#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) .prompt-manager-toggle-action {
    color: var(--wg-ink);
}

#completion_prompt_manager .completion_prompt_manager_header,
#completion_prompt_manager .completion_prompt_manager_header * {
    color: var(--wg-ink-soft);
}

/* ---- 간격과 가독성 ---- */

/* 패널 안쪽 여백 */
.drawer-content {
    padding: 10px 12px;
}

/* 접기 머리 — 줄 사이를 띄우고 높이를 고르게 */
#extensions_settings .inline-drawer,
#extensions_settings2 .inline-drawer {
    margin-bottom: 8px;
}

#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
.standoutHeader.inline-drawer-header {
    min-height: 40px;
    box-sizing: border-box;
    padding: 8px 12px;
    margin-bottom: 0;
    gap: 10px;
    align-items: center;
}

#extensions_settings .inline-drawer-content,
#extensions_settings2 .inline-drawer-content {
    padding: 10px 12px 12px;
}

#extensions_settings hr.sysHR,
#extensions_settings2 hr.sysHR {
    margin: 4px 0;
}

/* 월드 인포 항목 — 카드 사이와 안쪽을 넉넉하게 */
#world_popup_entries_list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    padding: 4px 2px 12px;
}

#world_popup_entries_list .world_entry {
    margin: 0;
}

#world_popup_entries_list .world_entry > form,
#world_popup_entries_list .world_entry .world_entry_form {
    border: 1px solid var(--wg-ui-line) !important;
    border-radius: 6px !important;
    background-color: #ffffff;
}

#world_popup_entries_list .world_entry .inline-drawer-header {
    padding: 12px 12px 10px;
    gap: 10px;
    align-items: flex-start;
}

#world_popup_entries_list .world_entry .inline-drawer-header .flex-container {
    gap: 8px 10px;
}

#world_popup_entries_list .world_entry_form_control {
    gap: 4px;
}

#world_popup_entries_list .world_entry_form_control label,
#world_popup_entries_list .world_entry_form_control small,
#world_popup_entries_list .world_entry_form_control h4,
#world_popup_entries_list .world_entry_form_control h5 {
    color: var(--wg-ink-soft);
    font-size: calc(var(--mainFontSize) * 0.9);
}

#world_popup_entries_list .world_entry .inline-drawer-content {
    padding: 0 12px 12px;
    border-top: 1px solid var(--wg-ui-line);
}

#world_popup .world_entry .killSwitch {
    color: var(--wg-ink);
}

/* 입력칸 — 조금 더 높게 */
.text_pole,
select {
    min-height: 2.2em;
    padding: 4px 8px;
    border-radius: 4px;
}

/* 작은 안내 글씨 */
.drawer-content small,
.drawer-content .notes-link,
.drawer-content .text_muted {
    color: var(--wg-ink-soft);
}

/* ---- 캐릭터 목록 · 페르소나 ---- */

/* 목록 위 도구 줄 */
#rm_characters_block .rm_tag_controls,
#rm_characters_block #charListGridToggle,
#rm_button_bar,
#rm_print_characters_pagination,
#persona-management-block .paginationjs {
    gap: 8px;
}

#rm_characters_block > .flex-container,
#persona-management-block > .flex-container {
    gap: 8px;
    margin-bottom: 8px;
}

/* 목록 줄 — 사진 · 이름 · 설명을 한 줄씩, 사이는 가는 괘선 */
#rm_print_characters_block .character_select,
#rm_print_characters_block .group_select,
#rm_print_characters_block .bogus_folder_select,
#user_avatar_block:not(.gridView) .avatar-container {
    flex-wrap: nowrap;
    gap: 12px;
    padding: 10px 6px;
    margin: 0;
    border: 0;
    border-bottom: 1px solid var(--wg-ui-line);
    border-radius: 0;
    outline: 0;
}

#rm_print_characters_block .character_select:hover,
#rm_print_characters_block .group_select:hover,
#rm_print_characters_block .bogus_folder_select:hover,
#user_avatar_block .avatar-container:hover,
#user_avatar_block .avatar-container.selected {
    background-color: var(--wg-ui-wash);
}

#rm_print_characters_block .character_select > .flex-container,
#rm_print_characters_block .character_select > div:not(.avatar),
#user_avatar_block .avatar-container > div:not(.avatar) {
    flex: 1 1 0;
    min-width: 0;
}

#rm_print_characters_block .character_name_block,
#user_avatar_block .avatar-container .character_name_block {
    margin-bottom: 4px;
    align-items: baseline;
}

#rm_print_characters_block .ch_name,
#user_avatar_block .ch_name {
    font-family: var(--wg-title);
    font-weight: 700;
    color: var(--wg-ink);
}

#rm_print_characters_block .ch_description,
#user_avatar_block .ch_description,
#rm_print_characters_block .character_version,
#user_avatar_block .ch_additional_info {
    margin-top: 0;
    line-height: 1.6;
    color: var(--wg-ink-soft);
}

/* 목록 사진 — 둥근 모서리 대신 각진 사진, 가는 선 */
#rm_print_characters_block .avatar,
#rm_print_characters_block .avatar img,
#user_avatar_block .avatar,
#user_avatar_block .avatar img {
    border-radius: 2px !important;
}

/* 페르소나 — 선택된 항목은 왼쪽에 먹색 괘선 */
#user_avatar_block .avatar-container.selected {
    box-shadow: inset 3px 0 0 var(--wg-ink) !important;
}

/* 격자 보기 — 캐릭터·페르소나 모두 같은 카드 */
body.charListGrid #rm_print_characters_block,
#user_avatar_block.gridView {
    gap: 10px;
    justify-content: flex-start;
    padding-top: 4px;
}

body.charListGrid #rm_print_characters_block .character_select,
body.charListGrid #rm_print_characters_block .group_select,
body.charListGrid #rm_print_characters_block .bogus_folder_select,
#user_avatar_block.gridView .avatar-container {
    width: calc((100% - 20px) / 3);
    max-width: none;
    box-sizing: border-box;
    align-items: center;
    gap: 8px;
    padding: 10px 6px 8px;
    margin: 0;
    border: 1px solid var(--wg-ui-line);
    border-radius: 3px;
    outline: 0;
}

body.charListGrid #rm_print_characters_block .character_select > div:not(.avatar),
#user_avatar_block.gridView .avatar-container > div:not(.avatar) {
    flex: none;
    width: 100%;
}

body.charListGrid #rm_print_characters_block .ch_name,
#user_avatar_block.gridView .avatar-container .ch_name,
#user_avatar_block.gridView .avatar-container .ch_additional_info {
    max-width: none;
    text-align: center;
}

/* 선택된 카드는 먹색 테두리 */
#user_avatar_block.gridView .avatar-container.selected {
    box-shadow: none !important;
    border-color: var(--wg-ink);
}

/* 현재 페르소나 영역 */
#persona_controls {
    gap: 8px;
    margin-top: 10px;
}

/* 햄버거 메뉴 · 확장 메뉴 · 팝업 메뉴 — 그림자 없이 선 하나 */
#options,
#extensionsMenu,
.popup .popper-modal {
    box-shadow: none !important;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    background-color: var(--wg-paper);
    border: 1px solid var(--wg-ui-line);
    border-radius: 6px;
}

/* 확장 메뉴는 확장마다 항목 상자를 덧붙이므로, 안쪽 요소와 메뉴를 띄우는 상자까지 모두 그림자를 걷어 냅니다 */
#extensionsMenu *,
#extensionsMenu .extension_container > div,
#extensionsMenu .list-group-item,
[data-popper-placement],
.popper,
.tippy-box {
    box-shadow: none !important;
    filter: none !important;
    text-shadow: none !important;
}

[data-popper-placement]:has(> #extensionsMenu),
[data-popper-placement]:has(> #options) {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#options .options-content,
#extensionsMenu .options-content {
    border: 0;
    box-shadow: none !important;
}

#options hr,
#extensionsMenu hr {
    border: 0;
    border-top: 1px solid var(--wg-ui-line);
    opacity: 1;
}

/* 알림 */
#toast-container > div {
    background-color: var(--wg-paper);
    color: var(--wg-ink);
    border: 1px solid var(--wg-ui-line);
    opacity: 1;
}

#toast-container > .toast-success { border-left: 4px solid var(--wg-ink-faint) !important; }
#toast-container > .toast-info { border-left: 4px solid var(--wg-ui-line) !important; }
#toast-container > .toast-warning { border-left: 4px solid var(--wg-ink-soft) !important; }
#toast-container > .toast-error { border-left: 4px solid var(--wg-ink) !important; }

/* ----------------------------------------------------------------------------
   스크롤바
   ---------------------------------------------------------------------------- */

::-webkit-scrollbar-thumb {
    background-color: rgba(28, 30, 33, 0.22);
    border-radius: 8px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

/* ----------------------------------------------------------------------------
   움직임 줄이기
   ---------------------------------------------------------------------------- */

@media (prefers-reduced-motion: reduce) {
    #chat .mes .avatar,
    #chat .mes .avatar:hover {
        transition: none;
        transform: rotate(var(--wg-tilt));
    }
}

/* 아바타를 숨기면 구분 줄도 폴라로이드 자리를 비우지 않습니다 */
body.hideChatAvatars #chat .mes .mes_buttons,
body.hideChatAvatars #chat .mes .mes_edit_buttons {
    margin-top: 6px;
}


/* ==========================================================================
   1.0.4 — 원고지 헤더의 정렬과 인쇄 밀도 보강
   본문·메뉴·입력창·사진 크기·원본 색상 설정은 1.0.3을 유지합니다.
   ========================================================================== */
#chat .mes {
    min-width: 0;
    box-sizing: border-box;
}
/* 기본 flex 유틸리티의 최소 폭/줄바꿈이 격자 폭을 밀어내지 않도록 합니다. */
#chat .mes .ch_name > .flex-container > .flex-container {
    min-width: 0;
    max-width: 100%;
    flex-wrap: nowrap;
    align-content: initial;
    margin-bottom: 28px;
    container-type: inline-size;
    container-name: wg-header;
}
#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container {
    margin-bottom: 28px;
}
#chat .mes .ch_name > .flex-container > .flex-container > .name_text {
    min-width: 0;
    max-width: 100%;
    height: auto;
    overflow-wrap: anywhere;
    white-space: normal;
}
/* 첫 줄의 작은 편집 표식. 번호 반대편에 놓으며 원래의 한 행 높이를 유지합니다. */
#chat .mes .ch_name > .flex-container > .flex-container::before {
    content: '記録';
    flex: 0 0 var(--wg-pitch);
    height: var(--wg-pitch);
    min-height: var(--wg-pitch);
    top: 0;
    box-sizing: border-box;
    font-family: var(--wg-hanja);
    font-size: 9px;
    font-weight: 400;
    line-height: var(--wg-pitch);
    letter-spacing: .22em;
    word-spacing: normal;
    text-align: left;
    color: var(--wg-ink-faint);
    pointer-events: none;
}
#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container::before {
    content: '答書';
    text-align: right;
}
/* 한글/영문 긴 이름은 칸의 높이를 늘리고, 날짜는 그 아래의 지정 영역에 머뭅니다. */
#chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    top: calc(100% + 7px);
    right: 0;
    left: auto;
    width: auto !important;
    max-width: calc(100% - var(--wg-pol-w) * .58 - 10px) !important;
    height: 16px;
    font-size: 9.5px !important;
    font-weight: 400;
    line-height: 16px !important;
    letter-spacing: .015em !important;
    word-spacing: 0;
    white-space: nowrap !important;
    overflow: hidden;
    text-overflow: ellipsis;
}
#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container > .timestamp {
    left: 0;
    right: auto;
}
/* 사진 위 표제/토큰과 생성 시간을 서로 다른 높이에 두어 겹침을 막습니다. */
#chat .mes .tokenCounterDisplay,
#chat .mes .ch_name::after {
    max-width: calc(100% - var(--wg-side) * 2 - var(--wg-pol-w) - 12px);
    overflow: hidden;
    text-overflow: ellipsis;
    font-size: 9px;
    letter-spacing: .10em;
}
#chat .mes .mes_timer {
    top: calc(var(--wg-pad) - 36px);
    font-size: 9px;
    line-height: 12px;
}
/* 가운데 버튼을 양쪽 괘선에 조금 더 단단하게 연결합니다. */
#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons {
    min-width: 0;
    max-width: 100%;
    flex-wrap: wrap;
    row-gap: 4px;
}
#chat .mes .mes_buttons::before,
#chat .mes .mes_buttons::after,
#chat .mes .mes_edit_buttons::before,
#chat .mes .mes_edit_buttons::after {
    height: 4px;
    margin-inline: 7px;
}
#chat .mes .mes_buttons > .mes_button {opacity: .52;}
#chat .mes .mes_buttons > .mes_button:hover {opacity: 1;}
/* 좁은 헤더에서는 번호와 이름을 우선하고 표식은 행 높이만 남깁니다. */
@container wg-header (max-width: 180px) {
    #chat .mes .ch_name > .flex-container > .flex-container::before {visibility: hidden;}
}
@media (max-width: 600px) {
    #chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
        font-size: 8.5px !important;
        letter-spacing: 0 !important;
    }
    #chat .mes .mes_buttons,
    #chat .mes .mes_edit_buttons {margin-bottom: 10px;}
}
body.hideChatAvatars #chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    max-width: calc(100% - 8px) !important;
}

/* ======================================================================
   Wongoji 1.0.5 — literary archive ornaments, CSS only
   Photographs, manuscript grids and reading text retain the 1.0.4 layout.
   ====================================================================== */
#chat .mes {
    --wg-ornament: #73818a;
    --wg-hairline: rgba(82, 96, 108, .25);
    --wg-stamp: #575f65;
}
#chat .mes[is_user="true"] {
    --wg-ornament: #7d8d9b;
    --wg-hairline: rgba(109,127,145,.26);
    --wg-stamp: #6d7f91;
}
/* A miniature archive heading occupies existing space above the paper. */
#chat .mes::after {
    content: 'LITERARY ARCHIVE  /  CHARACTER';
    position: absolute;
    top: calc(var(--wg-pad) - 44px);
    left: calc(var(--wg-side) + var(--wg-pol-w) + 8px);
    right: var(--wg-side);
    min-width: 0;
    height: 12px;
    border-top: 1px solid var(--wg-hairline);
    padding-top: 5px;
    font: 7px/10px var(--wg-mono);
    letter-spacing: .12em;
    color: var(--wg-ornament);
    text-align: left;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    pointer-events: none;
    z-index: 1;
}
#chat .mes[is_user="true"]::after {
    content: 'LITERARY ARCHIVE  /  CORRESPONDENCE';
    left: var(--wg-side);
    right: calc(var(--wg-side) + var(--wg-pol-w) + 8px);
    text-align: right;
}
/* Four corner mounts, delicate inner frame, and an engraved caption rail. */
#chat .mes .avatar {
    overflow: visible;
    isolation: isolate;
    outline: 1px solid rgba(28,30,33,.16);
    outline-offset: 3px;
    background-color: #fff;
    background-image:
        linear-gradient(135deg, var(--wg-band-frame) 0 46%, transparent 48%),
        linear-gradient(225deg, var(--wg-band-frame) 0 46%, transparent 48%),
        linear-gradient(45deg, var(--wg-band-frame) 0 46%, transparent 48%),
        linear-gradient(315deg, var(--wg-band-frame) 0 46%, transparent 48%),
        repeating-linear-gradient(0deg, transparent 0 3px, rgba(100,100,100,.035) 3px 4px);
    background-size: 5px 5px, 5px 5px, 5px 5px, 5px 5px, 100% 100%;
    background-position: 2px 2px, right 2px top 2px, left 2px bottom 2px, right 2px bottom 2px, 0 0;
    background-repeat: no-repeat;
}
/* A wire paper clip: its interior stays open, keeping the photo visible. */
#chat .mes .avatar::before {
    content: '';
    position: absolute;
    top: -13px;
    left: 17px;
    width: 10px;
    height: 30px;
    border: 1px solid var(--wg-ornament);
    border-bottom-width: 2px;
    border-radius: 7px 7px 6px 6px;
    outline: 1px solid rgba(255,255,255,.85);
    outline-offset: 1px;
    background: linear-gradient(var(--wg-ornament),var(--wg-ornament)) center 7px / 1px 17px no-repeat;
    transform: rotate(12deg);
    z-index: 4;
    pointer-events: none;
}
#chat .mes[is_user="true"] .avatar::before {
    left: auto;
    right: 17px;
    transform: rotate(-12deg);
}
#chat .mes .avatar img {outline: 1px solid var(--wg-hairline); outline-offset: 2px;}
#chat .mes .avatar::after {
    padding-top: 3px;
    border-top: 1px solid var(--wg-hairline);
    background:
        radial-gradient(circle, var(--wg-ornament) 0 1px, transparent 1.3px) left center / 3px 3px no-repeat,
        linear-gradient(var(--wg-hairline),var(--wg-hairline)) left 8px center / 15% 1px no-repeat;
}
#chat .mes[is_user="true"] .avatar::after {
    background-position: right center, right 8px center;
}
/* Offset paper edges, subtle fibres, and a complete two-row printed grid. */
#chat .mes .ch_name > .flex-container > .flex-container {
    margin-bottom: 34px;
    box-shadow:
        3px 3px 0 0 var(--wg-paper),
        4px 4px 0 0 var(--wg-hairline),
        7px 7px 0 0 var(--wg-paper),
        8px 8px 0 0 var(--wg-hairline);
    background-image:
        linear-gradient(to bottom,
            transparent var(--wg-gap),
            var(--wg-band-line) var(--wg-gap), var(--wg-band-line) calc(var(--wg-gap) + 1px),
            transparent calc(var(--wg-gap) + 1px), transparent calc(var(--wg-pitch) - 1px),
            var(--wg-band-line) calc(var(--wg-pitch) - 1px)),
        linear-gradient(to bottom,var(--wg-band-bg) var(--wg-gap),transparent var(--wg-gap)),
        linear-gradient(to right,var(--wg-band-line) 1px,transparent 1px),
        radial-gradient(ellipse,rgba(100,110,120,.065) 0 .5px,transparent .8px),
        repeating-linear-gradient(115deg,transparent 0 5px,rgba(90,100,110,.025) 5px 6px);
    background-size: 100% var(--wg-pitch), 100% var(--wg-pitch), var(--wg-cell) 100%, 7px 9px, 100% 100%;
    background-position: 0 0, 0 0, right -1px top 0, 0 0, 0 0;
}
#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container {
    margin-bottom: 34px;
    box-shadow:
        -3px 3px 0 0 var(--wg-paper),
        -4px 4px 0 0 var(--wg-hairline),
        -7px 7px 0 0 var(--wg-paper),
        -8px 8px 0 0 var(--wg-hairline);
    background-position: 0 0, 0 0, left -1px top 0, 0 0, 0 0;
}
/* A small publisher-style seal uses the first row opposite the chat number. */
#chat .mes .ch_name > .flex-container > .flex-container::before {
    content: '\00a0';
    visibility: visible;
}
#chat .mes .ch_name > .flex-container > .flex-container::after {
    content: '文';
    position: absolute;
    top: calc(var(--wg-gap) + 3px);
    left: calc(var(--wg-pol-w) * .58 + 12px);
    width: calc(var(--wg-cell) * .62);
    height: calc(var(--wg-cell) * .62);
    display: grid;
    place-items: center;
    border: 1px solid var(--wg-stamp);
    outline: 1px solid var(--wg-hairline);
    outline-offset: 2px;
    background: var(--wg-band-bg);
    font-family: var(--wg-hanja);
    font-size: calc(var(--wg-cell) * .37);
    font-weight: 400;
    line-height: 1;
    letter-spacing: 0;
    color: var(--wg-stamp);
    transform: rotate(-7deg);
    opacity: .65;
    pointer-events: none;
    z-index: 1;
}
#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container::after {
    content: '書';
    left: auto;
    right: calc(var(--wg-pol-w) * .58 + 12px);
    transform: rotate(7deg);
}
#chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    top: calc(100% + 14px);
}
/* Small ornaments tie the edit controls to the manuscript's lower edge. */
#chat .mes .mes_buttons::before,
#chat .mes .mes_buttons::after,
#chat .mes .mes_edit_buttons::before,
#chat .mes .mes_edit_buttons::after {
    content: '❧';
    height: 14px;
    min-width: 16px;
    border: 0;
    font: 16px/14px Georgia,serif;
    color: var(--wg-ornament);
    text-align: center;
    background:
        linear-gradient(var(--wg-hairline),var(--wg-hairline)) left center / calc(50% - 12px) 1px no-repeat,
        linear-gradient(var(--wg-hairline),var(--wg-hairline)) right center / calc(50% - 12px) 1px no-repeat;
    pointer-events: none;
}
#chat .mes .mes_buttons::after,
#chat .mes .mes_edit_buttons::after {transform: scaleX(-1);}
/* The seal yields to long numbers in very narrow header columns. */
@container wg-header (max-width: 150px) {
    #chat .mes .ch_name > .flex-container > .flex-container::after {display:none;}
}
@media(max-width:600px) {
    #chat .mes::after {font-size: 6.5px;letter-spacing: .06em;top:calc(var(--wg-pad) - 42px);}
    #chat .mes .avatar::before {width:8px;height:25px;top:-10px;left:12px;background-size:1px 14px;}
    #chat .mes[is_user="true"] .avatar::before {left:auto;right:12px;}
    #chat .mes .avatar {outline-offset:2px;}
}
body.hideChatAvatars #chat .mes::after {left:var(--wg-side);right:var(--wg-side);}
body.hideChatAvatars #chat .mes .avatar::before,
body.hideChatAvatars #chat .mes .avatar::after {display:none;}
/* If generation time is enabled, give it its own rail above the archive heading. */
#chat .mes .mes_timer {top:calc(var(--wg-pad) - 58px);}


/* ======================================================================
   Wongoji 1.0.6 — legible seals and Latin manuscript nameplates
   Seal contrast retained; name layout is superseded by 1.0.7 below.
   ====================================================================== */
#chat .mes { --wg-stamp: #39434b; }
#chat .mes[is_user="true"] { --wg-stamp: #485f73; }
#chat .mes .ch_name > .flex-container > .flex-container::after {
