    border: 1.5px solid var(--wg-stamp);
    outline: 1px solid var(--wg-stamp);
    outline-offset: 2px;
    background: #fff;
    color: var(--wg-stamp);
    font-size: calc(var(--wg-cell) * .48);
    font-weight: 700;
    text-shadow: none;
