/* .ch_name is display:contents; its positioned ornament anchors to .mes. */
#chat .mes .ch_name::before {
    content: '';
    display: block;
    position: absolute;
    top: calc(var(--wg-pad) - 33px);
    right: calc(var(--wg-side) + 2px);
    left: auto;
    width: var(--wg-flight-width);
    height: 30px;
    background: var(--wg-flight-art) center / contain no-repeat;
    pointer-events: none;
    user-select: none;
    z-index: 2;
}
#chat .mes[is_user="true"] .ch_name::before {
    right: auto;
    left: calc(var(--wg-side) + 2px);
    transform: scaleX(-1);
}
/* Reserve the outer end of the paper-label rail for the birds. */
#chat .mes .tokenCounterDisplay,
#chat .mes .ch_name::after {
    max-width: max(0px, calc(100% - var(--wg-side) * 2 - var(--wg-pol-w) - var(--wg-flight-width) - 16px));
}
/* Anchor below the final name line, so wrapped names move the feather too. */
#chat .mes .ch_name > .flex-container > .flex-container > .name_text::after {
    content: '';
    display: block;
    position: absolute;
    top: calc(100% + 16px);
    left: 0;
    right: auto;
    width: var(--wg-feather-width);
    height: 20px;
    background: var(--wg-feather-art) center / contain no-repeat;
    pointer-events: none;
    user-select: none;
    z-index: 1;
}
#chat .mes[is_user="true"] .ch_name > .flex-container > .flex-container > .name_text::after {
    left: auto;
    right: 0;
    transform: scaleX(-1);
}
#chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    max-width: max(0px, calc(100% - var(--wg-pol-w) * .58 - var(--wg-feather-reserve))) !important;
}
body.hideChatAvatars #chat .mes .ch_name > .flex-container > .flex-container > .timestamp {
    max-width: max(0px, calc(100% - var(--wg-feather-reserve))) !important;
}
@media (max-width: 600px) {
    #chat .mes {
        --wg-flight-width: 58px;
        --wg-feather-width: 40px;
        --wg-feather-reserve: 56px;
    }
    #chat .mes .ch_name::before {
        top: calc(var(--wg-pad) - 29px);
        height: 26px;
    }
}

